static void bcm_sysport_fini_tx_ring ( struct bcm_sysport_priv * priv , unsigned int index ) { struct bcm_sysport_tx_ring * ring = & priv -> tx_rings [ index ] ; struct device * kdev = & priv -> pdev -> dev ; u32 reg ; reg = tdma_readl ( priv , TDMA_STATUS ) ; if ( ! ( reg & TDMA_DISABLED ) ) { netdev_warn ( priv -> netdev , "TDMA not stopped!\n" ) ; } if ( ! ring -> cbs ) { return ; } napi_disable ( & ring -> napi ) ; netif_napi_del ( & ring -> napi ) ; bcm_sysport_tx_clean ( priv , ring ) ; ring -> cbs = NULL ; if ( ring -> desc_dma ) { dma_free_coherent ( kdev , sizeof ( dma_desc ) , ring -> desc_cpu , ring -> desc_dma ) ; ring -> desc_dma = 0 ; } ring -> size = 0 ; ring -> alloc_size = 0 ; netif_dbg ( priv , hw , priv -> netdev , "TDMA fini done\n" ) ; } 